import{_ as e,o as s,c as t,ag as i}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-11-06（材料 · 单个缺陷的原子级发光）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-11-06-materials.md","filePath":"topics/materials/science-daily-2026-11-06-materials.md"}'),c={name:"topics/materials/science-daily-2026-11-06-materials.md"};function r(n,o,a,l,d,g){return s(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="科学日报-·-2026-11-06-材料-·-单个缺陷的原子级发光" tabindex="-1">科学日报 · 2026-11-06（材料 · 单个缺陷的原子级发光） <a class="header-anchor" href="#科学日报-·-2026-11-06-材料-·-单个缺陷的原子级发光" aria-label="Permalink to &quot;科学日报 · 2026-11-06（材料 · 单个缺陷的原子级发光）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> — 第56期 ｜ 科学板块（材料/光谱向 1 篇） 落盘说明：文件名带 <code>-materials</code> 后缀，避免与其它主题同日同名文件互引产生伪边。</p></blockquote><hr><h2 id="科学日报-2026-11-06-材料-·-1-1-在同一个缺陷上-同时看到「原子」与「光」" tabindex="-1">科学日报 2026-11-06（材料 · 1/1）：在同一个缺陷上，同时看到「原子」与「光」 <a class="header-anchor" href="#科学日报-2026-11-06-材料-·-1-1-在同一个缺陷上-同时看到「原子」与「光」" aria-label="Permalink to &quot;科学日报 2026-11-06（材料 · 1/1）：在同一个缺陷上，同时看到「原子」与「光」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-06.md</code> ｜ DOI: 10.1038/s41565-026-02314-x ｜ Nature Nanotechnology (2026)</p></blockquote><ul><li>问题：<strong>激子（电子—空穴对）</strong> 决定半导体光学响应，是<strong>光伏与量子光源</strong>的基础；纳米尺度下激子<strong>空间尺度逼近原子量级</strong>，但<strong>在实空间直接成像激子过程</strong>一直困难。二维半导体（TMD）缺陷发光的<strong>微观起源</strong>与<strong>样品间差异</strong>长期有争议。</li><li>方法：用<strong>扫描隧道显微镜诱导发光（STM-induced luminescence）</strong> 在<strong>单层 MoS₂</strong> 上做<strong>原子分辨</strong>测量；关键是用<strong>双层六方氮化硼（hBN）把材料与衬底解耦</strong>，以抑制衬底淬灭、凸显本征发射。</li><li>结果（实测）： <ul><li>同时获得<strong>单个缺陷的原子结构与光学指纹</strong>；</li><li>探测到<strong>尖锐的激子发射</strong>与<strong>空间局域的缺陷发射</strong>，并将其归因于<strong>自由—束缚复合（free-to-bound, e,A⁰）</strong>；</li><li>绘制了该发射在样品上的空间分布，把<strong>结构缺陷与光学行为在同一位置直接对应</strong>。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>physics</code>）： <ol><li><strong>「把两种表征对齐到同一个像素上」</strong>——过去原子结构（STM）与光学（荧光）往往<strong>不在同一缺陷上</strong>，结论只能靠统计推断；本文让二者<strong>空间重合</strong>，因果才立得住；判据：<strong>要断言『结构 A 导致现象 B』，先让 A、B 在同一对象上被同时观测</strong>（呼应母题「<strong>否证性判据优于肯定性判据</strong>」）。</li><li><strong>「解耦衬底 = 去掉混淆变量」</strong>——hBN 隔开衬底，消掉的正是过去导致『缺陷发光五花八门』的<strong>环境干扰</strong>；判据：<strong>当同一类对象表现出极大散布时，先怀疑是环境耦合而非本征差异</strong>。</li><li><strong>与库内呼应</strong>：与 <code>topics/materials/science-daily-2026-11-05-materials.md</code>、<code>topics/physics/science-daily-2026-11-03-physics.md</code>（WS₂ 激子—极化激元）同属 <strong>TMD 激子物理</strong>脉络。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ <code>topics/physics/spectroscopy.md</code> ｜ 第56期 科学板块</p></blockquote><p>关键词：科学日报第56期、单层MoS2、过渡金属硫属化物TMD、激子exciton、缺陷发光、扫描隧道显微镜诱导发光STM-induced luminescence、原子分辨、双层六方氮化硼hBN、衬底解耦、自由束缚复合free-to-bound e,A0、尖锐激子发射、空间局域缺陷发射、把结构与光学对齐到同一像素、去掉混淆变量、否证性判据、TMD激子物理</p><p>关联：<code>topics/materials/index.md</code>、<code>topics/materials/science-daily-2026-11-05-materials.md</code>、<code>topics/physics/spectroscopy.md</code>、<code>topics/physics/science-daily-2026-11-06-physics.md</code>、<code>ScienceDaily/daily/2026-11-06.md</code></p>',10)])])}const u=e(c,[["render",r]]);export{m as __pageData,u as default};
